#include <cstdio>
#include <algorithm>

using namespace std;

const int maxN = 1000; // Assuming a reasonable maximum size
int data[maxN];

int main() {
    int N;

    while (1) {
        scanf("%d", &N);
        if (N == 0) break;

        for (int i = 0; i < N; i++) {
            scanf("%d", &data[i]);
        }

        // Use a single loop to check both conditions simultaneously
        int count = 0;
        bool hasGreaterThanOne = false;

        for (int i = 0; i < N; i++) {
            if (data[i] > 1) {
                hasGreaterThanOne = true;
            }
            if (data[i] != 0) {
                count++;
            }
        }

        if (!hasGreaterThanOne) {
            printf("NA\n");
        } else {
            printf("%d\n", (N == 1) ? 2 : count + 1);
        }
    }
    return 0;
}

