            scanf("%d", &data[i]);
        }

        if (none_of(data, data + N, [](int x) { return x > 1; })) {
            printf("NA\n");
        } else {
            printf("%d\n", (N == 1) ? 2 : (count_if(data, data + N, [](int x) { return x != 0; }) + 1));
        }
    }
    return 0;
}

